const rows = $input.all().map(i => i.json);
const triggerData = $('When Executed by Darwin').first().json;

function parseMessage(raw) {
  let msg = raw;
  if (typeof msg === 'string') {
    try { msg = JSON.parse(msg); } catch (e) { return null; }
  }
  if (!msg || typeof msg !== 'object') return null;
  let role = msg.role || msg.type || (msg.data && msg.data.type);
  let content = msg.content;
  if (content === undefined && msg.data) content = msg.data.content;
  if (role === 'human') role = 'user';
  if (role === 'ai') role = 'assistant';
  if (content === undefined || content === null) return null;
  if (typeof content !== 'string') content = JSON.stringify(content);
  return { role, content };
}

const messages = [];
for (const r of rows) {
  const parsed = parseMessage(r.message);
  if (parsed) messages.push(parsed);
}

let lastUserIdx = -1;
for (let i = messages.length - 1; i >= 0; i--) {
  if (messages[i].role === 'user') { lastUserIdx = i; break; }
}
let lastAssistantIdx = -1;
for (let i = messages.length - 1; i >= 0; i--) {
  if (messages[i].role === 'assistant') { lastAssistantIdx = i; break; }
}

const input = lastUserIdx >= 0 ? messages[lastUserIdx].content : '';
const assistantLast = lastAssistantIdx >= 0 ? messages[lastAssistantIdx].content : '';

const excludeIdx = new Set();
if (lastUserIdx >= 0) excludeIdx.add(lastUserIdx);
if (lastAssistantIdx >= 0) excludeIdx.add(lastAssistantIdx);
const contextMessages = messages.filter((m, idx) => !excludeIdx.has(idx));

const override = (triggerData.expected_response || '').trim();
const expected_response = override !== '' ? override : assistantLast;

const case_id = 'eval-' + Date.now();

return [{ json: {
  case_id,
  input,
  context_turns: contextMessages.length,
  suite: 'eval',
  inputs_json: JSON.stringify({ prompt: input }),
  eval_config_json: JSON.stringify({
    context_messages: contextMessages,
    prohibited_tools: triggerData.prohibited_tools || '',
    expected_tools: triggerData.expected_tools || '',
    expected_response,
    source_thread: triggerData.source_thread || '',
    created_at: new Date().toISOString()
  }),
  description: input.slice(0, 200)
} }];
